"""Offline inspection report using only saved simulation results; no CDN required."""
from pathlib import Path
import html
import json
import base64
from .config import ROOT


def make_report(output, cfg, views, summary):
    output = Path(output)
    data = json.dumps(dict(config=cfg,views=views,summary=summary),ensure_ascii=False).replace("</","<\\/")
    template = '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>视点规划仿真 · myCobot 280</title><style>
:root{font-family:Inter,"Microsoft YaHei",system-ui,sans-serif;color:#dde5ef;background:#0b111a;font-synthesis:none}*{box-sizing:border-box}body{margin:0}header{padding:28px 4vw 20px;border-bottom:1px solid #253142;display:flex;justify-content:space-between;align-items:center}small,.label{color:#8c9bad;font-size:12px;letter-spacing:1px}h1{font-size:25px;margin:8px 0}h2{font-size:16px;font-weight:500;margin:0}.badge{border:1px solid #284f46;background:#122e28;padding:8px 14px;border-radius:24px;color:#71dfbf}.warning{color:#ffc96c}.wrap{max-width:1500px;margin:auto;padding:24px 4vw}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:22px}.stat,.panel{border:1px solid #253142;background:#111a26;border-radius:10px;overflow:hidden}.stat{padding:18px}.value{font-size:28px;margin-top:6px}.layout{display:grid;grid-template-columns:1.55fr 1fr;gap:18px}.top{padding:17px 20px;border-bottom:1px solid #253142;display:flex;justify-content:space-between;align-items:center}.panel img{display:block;width:100%;background:#fff}.camera{background:#0b111a;padding:15px}.camera img{border-radius:5px}.tabs{display:flex;gap:7px}button,select{font:inherit;background:#182637;color:#b8c9dc;border:1px solid #34475c;padding:7px 11px;border-radius:5px;cursor:pointer}button.active{color:#79ebc7;border-color:#39a68c}button:hover{background:#26364a}.details{padding:18px 20px;font-size:13px;line-height:1.6}.kv{display:flex;justify-content:space-between;border-bottom:1px solid #253142;padding:7px 0;gap:12px}.kv span:first-child{color:#8c9bad}.gallery{display:flex;gap:10px;overflow:auto;padding:15px}.thumb{flex-shrink:0;width:118px;padding:5px;border:1px solid #34475c;border-radius:6px;cursor:pointer;font-size:11px;color:#8c9bad}.thumb img{border-radius:3px;margin-bottom:6px}.thumb.on{border-color:#71dfbf;background:#19362f}.lower{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;border-bottom:1px solid #253142;padding:10px 8px}th{font-weight:400;color:#8c9bad}.legend{color:#8c9bad;font-size:12px;padding:0 20px 16px}.note{font-size:12px;color:#8c9bad;line-height:1.8;margin-top:22px}.rejections{padding:10px 20px}.barrow{display:grid;grid-template-columns:180px 1fr 35px;gap:8px;align-items:center;font-size:12px;margin:10px 0}.bar{background:#253142;height:7px;border-radius:4px}.bar i{display:block;background:#e6ab65;height:7px;border-radius:4px}.empty{padding:50px;text-align:center}.scatter{width:100%;height:250px}.scrub{display:flex;align-items:center;gap:12px;padding:12px 20px}input[type=range]{width:100%;accent-color:#71dfbf}a{color:#71dfbf;text-decoration:none}@media(max-width:850px){.layout,.lower{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.barrow{grid-template-columns:130px 1fr 30px}}
</style><header><div><small>ROBOT VISION / SIMULATION 0.1</small><h1>多高度约束随机视点规划</h1><small>myCobot 280 M5 · 腕部相机 · 理想 RGB-D · 可复现实验</small></div><div id="status" class="badge"></div></header>
<main class="wrap"><div class="stats"><div class="stat"><div class="label">通过全部筛选</div><div class="value" id="total"></div></div><div class="stat"><div class="label">随机采样通过率</div><div class="value" id="rate"></div></div><div class="stat"><div class="label">最小光轴夹角</div><div class="value" id="angle"></div></div><div class="stat"><div class="label">固定随机种子</div><div class="value" id="seed"></div></div></div>
<div class="layout"><section class="panel"><div class="top"><h2>工位与机械臂实际位姿</h2><select id="height"><option value="all">所有拍摄高度</option></select></div><img id="scene" alt="三维仿真渲染"><div class="scrub"><button id="prev">‹</button><input id="slider" type="range" min="0" value="0"><button id="next">›</button><span id="viewid" style="white-space:nowrap;font-size:12px"></span></div><div class="gallery" id="gallery"></div></section>
<section class="panel"><div class="top"><h2>相机画面</h2><div class="tabs"><button class="active" data-image="overlay">投影</button><button data-image="rgb">RGB</button><button data-image="food_mask">Mask</button><button data-image="crop_rgb">裁剪</button></div></div><div class="camera"><img id="camera" alt="实际相机渲染"></div><div class="legend">绿色：Food 3D ROI　黄色：Tray ROI　蓝色：裁剪框</div><div class="details" id="detail"></div></section></div>
<div class="lower"><section class="panel"><div class="top"><h2>各高度验收结果</h2></div><div class="details"><table id="heights"></table></div><div class="top"><h2>已接受相机 XY 分布</h2></div><svg class="scatter" id="scatter" viewBox="0 0 560 250" aria-label="Accepted XY viewpoints"></svg><div class="legend">颜色对应拍摄高度；每个点均经过几何、IK、碰撞、路径和图像检查。</div></section><section class="panel"><div class="top"><h2>候选拒绝原因</h2></div><div class="rejections" id="rejects"></div><div class="details"><table id="quality"></table></div></section></div>
<p class="note">本实验验证几何成像、随机位姿筛选、运动学可达性和离散路径碰撞。相机内外参、工位尺寸为示例配置。深度来自理想渲染，不包含双目匹配失败、反光、热环境、控制器到位和线缆约束。<br>原始数据：<a href="summary.json">summary.json</a> · <a href="views.json">views.json</a> · <a href="candidates.jsonl">candidates.jsonl</a> · <a href="config.json">config.json</a></p></main>
<script>const D=__DATA__;const $=id=>document.getElementById(id);const pct=x=>(x*100).toFixed(1)+'%';const num=(x,n=1)=>x==null?'—':x.toFixed(n);let selected=0,image='overlay',items=D.views;const colors=['#71dfbf','#74abf3','#ffc774','#cb9def'];
$('status').textContent=D.summary.complete?'全部高度完成':'有效位姿不足';if(!D.summary.complete)$('status').classList.add('warning');$('total').textContent=D.summary.accepted_total+' / '+D.summary.heights.reduce((s,h)=>s+h.target,0);$('rate').textContent=pct(D.summary.accepted_total/Math.max(1,D.summary.heights.reduce((s,h)=>s+h.attempts,0)));$('angle').textContent=num(D.summary.minimum_axis_angle_deg)+'°';$('seed').textContent=D.summary.seed;
D.summary.heights.forEach((h,i)=>{let o=document.createElement('option');o.value=i;o.textContent=Math.round(h.height_above_tray_m*1000)+' mm';$('height').append(o)});
$('heights').innerHTML='<tr><th>相对托盘高度</th><th>有效 / 目标</th><th>尝试次数</th><th>通过率</th></tr>'+D.summary.heights.map(h=>`<tr><td>${Math.round(h.height_above_tray_m*1000)} mm</td><td>${h.accepted} / ${h.target}</td><td>${h.attempts}</td><td>${pct(h.acceptance_rate)}</td></tr>`).join('');
const failures={};D.summary.heights.forEach(h=>Object.entries(h.rejections).forEach(([k,v])=>failures[k]=(failures[k]||0)+v));let max=Math.max(1,...Object.values(failures));$('rejects').innerHTML=Object.entries(failures).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="barrow"><span>${k}</span><div class="bar"><i style="width:${v/max*100}%"></i></div><span>${v}</span></div>`).join('')||'<p>无拒绝记录</p>';
function filter(){items=D.views.filter(v=>$('height').value==='all'||v.height_index==$('height').value);selected=0;$('slider').max=Math.max(0,items.length-1);$('gallery').innerHTML=items.map((v,i)=>`<div class="thumb" data-idx="${i}"><img src="${v.id}/rgb.png" alt="${v.id}">${v.id}<br>${Math.round(v.height_above_tray_m*1000)} mm</div>`).join('');document.querySelectorAll('.thumb').forEach(t=>t.onclick=()=>{selected=+t.dataset.idx;show()});show()}
function show(){if(!items.length){$('detail').textContent='此高度没有满足约束的位姿；请查看拒绝原因。';$('scene').removeAttribute('src');$('camera').removeAttribute('src');return}let v=items[selected];$('scene').src=v.id+'/overview.png';$('camera').src=v.id+'/'+image+'.png';$('slider').value=selected;$('viewid').textContent=(selected+1)+' / '+items.length;document.querySelectorAll('.thumb').forEach((t,i)=>t.classList.toggle('on',i===selected));let pos=v.T_BC_actual.slice(0,3).map(row=>num(row[3]*1000));let kv=[['候选 ID',v.id],['光心 Base XYZ',pos.join(' / ')+' mm'],['原图烤盘占比',pct(v.geometry.tray_ratio_raw)],['裁剪后烤盘占比',pct(v.tray_ratio_cropped)],['ROI 光学 Z 范围',num(v.geometry.roi_depth_min_m*1000)+' – '+num(v.geometry.roi_depth_max_m*1000)+' mm'],['相机倾角',num(v.geometry.tilt_deg)+'°'],['IK 相机位置误差',num(v.camera_position_error_m*1000,4)+' mm'],['路径节点数',v.path_q_rad.length]];$('detail').innerHTML=kv.map(([k,val])=>`<div class="kv"><span>${k}</span><span>${val}</span></div>`).join('');$('quality').innerHTML='<tr><th>食材</th><th>可见率</th><th>有效深度</th><th>像素数</th></tr>'+v.quality.map(q=>`<tr><td>${q.name}</td><td>${pct(q.visible_fraction)}</td><td>${pct(q.valid_depth_fraction)}</td><td>${q.visible_pixels}</td></tr>`).join('');plot(v.id)}
function plot(active){let sx=D.config.sampling.x_B_m,sy=D.config.sampling.y_B_m;const x=v=>50+(v-sx[0])/(sx[1]-sx[0])*460,y=v=>215-(v-sy[0])/(sy[1]-sy[0])*180;let svg='<rect x="50" y="35" width="460" height="180" fill="#0d1520" stroke="#34475c"/><text x="280" y="242" fill="#8c9bad" font-size="12">Base X / m</text>';let tray=D.config.roi.tray_corners_B;svg+=`<polygon points="${tray.map(p=>x(p[0])+','+y(p[1])).join(' ')}" fill="none" stroke="#5e6f83" stroke-dasharray="4 4"/>`;D.views.forEach(v=>{let a=v.T_BC_actual;svg+=`<circle cx="${x(a[0][3])}" cy="${y(a[1][3])}" r="${v.id===active?7:4}" fill="${colors[v.height_index%4]}"><title>${v.id}</title></circle>`});svg+=`<text x="50" y="230" fill="#8c9bad" font-size="10">${sx[0]}</text><text x="487" y="230" fill="#8c9bad" font-size="10">${sx[1]}</text><text x="6" y="40" fill="#8c9bad" font-size="10">${sy[1]}</text><text x="6" y="215" fill="#8c9bad" font-size="10">${sy[0]}</text>`;$('scatter').innerHTML=svg}
$('height').onchange=filter;$('slider').oninput=e=>{selected=+e.target.value;show()};$('prev').onclick=()=>{selected=Math.max(0,selected-1);show()};$('next').onclick=()=>{selected=Math.min(items.length-1,selected+1);show()};document.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>{image=b.dataset.image;document.querySelectorAll('[data-image]').forEach(t=>t.classList.toggle('active',t===b));show()});filter();</script></html>'''
    font=ROOT/'assets/fonts/viewpoint-ui.woff'
    if font.is_file():
        uri=base64.b64encode(font.read_bytes()).decode('ascii')
        css="@font-face{font-family:ViewpointUI;src:url(data:font/woff;base64,"+uri+") format('woff');font-weight:100 900}"
        template=template.replace('<style>','<style>'+css,1).replace('font-family:Inter,','font-family:ViewpointUI,Inter,',1)
    (output/"report.html").write_text(template.replace("__DATA__",data),encoding="utf-8")
